#!/bin/bash
# Align all CIC-DDoS2019 flows (no sampling) to get flow alignment and packet coverage.
#   03-11: read pcap/0311.pcap directly; one shard holds all 20.36 million flows
#   01-12: extract the zips on the fly and pipe them into align_stream.py (no 160 GB pcap on disk); a pipe can only be read once,
#          so load one flow part at a time (--part i/K), read the K parts in turn, then sum them with merge_align.py
# Usage: align_cicddos2019_full.sh [K, default 1]
# Requires: zips copied from the NAS to ~/datasets/cicddos2019/zips/; conn/0112/*.conn.log.labeled generated by run_cicddos2019_0112_full.sh.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
A=$HERE/../iot23/align_stream.py
D=/home/sixsquare/datasets/cicddos2019
K=${1:-1}

# The official 03-11 CSV has 482,799 groups of duplicate rows, so use the deduplicated one (dedup_conn.sh); 01-12 has no duplicates
[ -f "$D/conn/0311.dedup.conn.log.labeled" ] || "$HERE/dedup_conn.sh" "$D/conn/0311.conn.log.labeled" "$D/conn/0311.dedup.conn.log.labeled"
[ -f "$D/align/0311_dedup.json" ] || python3 -I "$A" "$D/conn/0311.dedup.conn.log.labeled" "$D/pcap/0311.pcap" \
    --cic --max-flows 25000000 --json "$D/align/0311_dedup.json"

c=$D/conn/0112.conn.log.labeled
[ -f "$c" ] || cat "$D"/conn/0112/*.conn.log.labeled > "$c"
parts=()
for ((i = 0; i < K; i++)); do
    p=$D/align/0112.part${i}of$K.json
    [ -f "$p" ] || python3 -I "$HERE/zip_pcap_concat.py" /dev/stdout "$D"/zips/PCAP-01-12_*.zip 2>> "$D/align/0112.concat.log" \
        | python3 -I "$A" "$c" /dev/stdin --cic --part "$i/$K" --max-flows 60000000 --json "$p"
    parts+=("$p")
done
python3 -I "$HERE/merge_align.py" "$D/align/0112.json" "${parts[@]}"
